            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "All the world knows me in my book, and my book in me.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "'T is so much to be a king, that he only is so by being so.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "We are born to inquire after truth; it belongs to a greater power to possess it.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I moreover affirm that our wisdom itself, and wisest consultations, for the most part commit themselves to the conduct of chance.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "What if he has borrowed the matter and spoiled the form, as it oft falls out?", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The oldest and best known evil was ever more supportable than one that was new and untried.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Not because Socrates said so,… I look upon all men as my compatriots.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "My appetite comes to me while eating.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There is no man so good, who, were he to submit all his thoughts and actions to the laws, would not deserve hanging ten times in his life.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Saturninus said, 'Comrades, you have lost a good captain to make him an ill general.'", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "A little folly is desirable in him that will not be guilty of stupidity.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Habit is a second nature.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "We seek and offer ourselves to be gulled.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I have never seen a greater monster or miracle in the world than myself.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Men are most apt to believe what they least understand.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I have here only made a nosegay of culled flowers, and have brought nothing of my own but the thread that ties them together.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Amongst so many borrowed things, I am glad if I can steal one, disguising and altering it for some new service.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I am further of opinion that it would be better for us to have no laws at all than to have them in so prodigious numbers as we have.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "For truth itself has not the privilege to be spoken at all times and in all sorts.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The diversity of physical arguments and opinions embraces all sorts of methods.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I have ever loved to repose myself, whether sitting or lying, with my heels as high or higher than my head.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "A good marriage would be between a blind wife and a deaf husband.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "A wise man sees as much as he ought, not as much as he can.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Age imprints more wrinkles in the mind than it does on the face.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Ambition is not a vice of little people.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "An untempted woman cannot boast of her chastity.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Confidence in another man's virtue is no light evidence of a man's own, and God willingly favors such a confidence.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Courtesy is a science of the highest importance.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Covetousness is both the beginning and the end of the devil's alphabet— the first vice in corrupt nature that moves, and the last which dies.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Death, they say, acquits us of all obligations.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Don't discuss yourself, for you are bound to lose; if you belittle yourself, you are believed; if you praise yourself, you are disbelieved.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Even from their infancy we frame them to the sports of love: their instruction, behavior, attire, grace, learning and all their words azimuth only at love.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Fame and tranquility can never be bedfellows.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Fashion is the science of appearances, and it inspires one with the desire to seem rather than to be.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Fortune, seeing that she could not make fools wise, has made them lucky.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Hath God obliged himself not to exceed the bounds of our knowledge?", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "He who establishes his argument by noise and command shows that his reason is weak.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "He who fears he shall suffer, already suffers what he fears.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "He who is not sure of his memory, should not undertake the trade of lying.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I care not so much what I am to others as what I am to myself. I will be rich by myself, and not by borrowing.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I do myself a greater injury in lying than I do him of whom I tell a lie.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I know well what I am fleeing from but not what I am in search of.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "I prefer the company of peasants because they have not been educated sufficiently to reason incorrectly.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "If you don't know how to die, don't worry; Nature will tell you what to do on the spot, fully and adequately.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "In plain truth, lying is an accursed vice. We are not men, nor have any other tie upon another, but by our word.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "In true education, anything that comes to our hand is as good as a book: the prank of a page-boy, the blunder of a servant, a bit of table talk— they are all part of the curriculum.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "It is good to rub and polish our brain against that of others.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "It is not death, it is dying that alarms me.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "It is the mind that maketh good or ill, That maketh wretch or happy, rich or poor.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "It should be noted that children at play are not playing about; their games should be seen as their most serious-minded activity.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Labour not after riches first, and think thou afterwards wilt enjoy them. He who neglecteth the present moment, throweth away all that he hath.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Love to his soul gave eyes; he knew things are not as they seem.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Make your educational laws strict and your criminal ones can be gentle; but if you leave youth its liberty you will have to dig dungeons for ages.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Marriage is like a cage; one sees the birds outside desperate to get in, and those inside equally desperate to get out.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Marriage, a market which has nothing free but the entrance.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "My life has been full of terrible misfortunes most of which never happened.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "No man is exempt from saying silly things; the mischief is to say them deliberately.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "No wind serves him who addresses his voyage to no certain port.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Not being able to govern events, I govern myself.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Nothing prints more lively in our minds than something we wish to forget.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Observe, observe perpetually.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Of all our infirmities, the most savage is to despise our being.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Once conform, once do what others do because they do it, and a kind of lethargy steals over all the finer senses of the soul.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Rejoice in the things that are present; all else is beyond thee.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "So it is with minds. Unless you keep them busy with some definite subject that will bridle and control them, they throw themselves in disorder hither and yon in the vague field of imagination.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The art of dining well is no slight art, the pleasure not a slight pleasure.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The ceaseless labour of your life is to build the house of death.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The entire lower world was created in the likeness of the higher world.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The most manifest sign of wisdom is a continual cheerfulness; her state is like that in the regions above the moon, always clear and serene.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The most profound joy has more of gravity than of gaiety in it.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The strangest, most generous, and proudest of all virtues is true courage.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The value of life lies not in the length of days, but in the use we make of them... Whether you find satisfaction in life depends not on your tale of years, but on your will.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The way of the world is to make laws, but follow custom.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The world is all a carcass and vanity, The shadow of a shadow, a play And in one word, just nothing.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The world is but a perpetual see-saw.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "The worst of my actions or conditions seem not so ugly unto me as I find it both ugly and base not to dare to avouch for them.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There are some defeats more triumphant than victories.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There is a plague on Man, the opinion that he knows something.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There is a sort of gratification in doing good which makes us rejoice in ourselves.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There is little less trouble in governing a private family than a whole kingdom.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There is no conversation more boring than the one where everybody agrees.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There is no passion so contagious as that of fear.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There is no pleasure to me without communication: there is not so much as a sprightly thought comes into my mind that it does not grieve me to have produced alone, and that I have no one to tell it to.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "There is nothing more notable in Socrates than that he found time, when he was an old man, to learn music and dancing, and thought it time well spent.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Those that will combat use and custom by the strict rules of grammar do but jest.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "'Tis the sharpness of our mind that gives the edge to our pains and pleasures.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Valor is stability, not of legs and arms, but of courage and the soul.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "We can be knowledgeable with other men's knowledge, but we cannot be wise with other men's wisdom.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "We only labor to stuff the memory, and leave the conscience and the understanding unfurnished and void.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "When I am attacked by gloomy thoughts, nothing helps me so much as running to my books. They quickly absorb me and banish the clouds from my mind.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Who does not in some sort live to others, does not live much to himself.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Wonder is the foundation of all philosophy, research is the means of all learning, and ignorance is the end.", Author = "Michel de Montaigne" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Michel_de_Montaigne", Text = "Writing does not cause misery. It is born of misery.", Author = "Michel de Montaigne" },
        };
    }
}